import { useState } from "react";
import {
  User,
  Lock,
  Eye,
  EyeOff,
  ArrowLeft,
  ArrowRight,
  AlertCircle,
  Loader2,
  ShieldCheck,
  GraduationCap,
  Landmark,
} from "lucide-react";

/*
  Add to index.html:
  <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700;800&family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet">

  Theme: navy #14234b · maroon #8f0014 · gold #f2c200
  Usage: <LoginPage onLogin={async ({ identifier, password, remember }) => { ...call your API... }} />
*/

// Campus photo (blurred background) and college crest, embedded as base64
const campusBg =
  "data:image/jpeg;base64,";
const logo =
  "data:image/png;base64,";

const HIGHLIGHTS = [
  { icon: ShieldCheck, title: "NAAC Grade A", text: "Accredited institution" },
  { icon: GraduationCap, title: "Affiliated to SPPU", text: "Arts, Science & Commerce (Autonomous)" },
  { icon: Landmark, title: "Since 1948", text: "M.C.E. Society, Pune" },
];

export default function LoginPage({ onLogin }) {
  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [remember, setRemember] = useState(false);
  const [show, setShow] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    if (!identifier.trim() || !password) {
      setError("Please enter your username/email and password.");
      return;
    }

    try {
      setLoading(true);
      if (onLogin) {
        await onLogin({ identifier: identifier.trim(), password, remember });
      } else {
        // Demo only – remove once you connect your real login API
        await new Promise((r) => setTimeout(r, 900));
        console.log("Login submitted", { identifier, remember });
      }
    } catch (err) {
      setError(err?.message || "Login failed. Please check your details and try again.");
    } finally {
      setLoading(false);
    }
  };

  const field =
    "flex h-12 items-center gap-3 rounded-lg border border-slate-300 bg-white px-4 transition focus-within:border-[#8f0014] focus-within:ring-4 focus-within:ring-[#8f0014]/10";

  return (
    <main className="relative isolate flex min-h-screen items-center justify-center overflow-hidden bg-[#14234b] px-4 py-16 font-['Poppins',sans-serif]">
      <style>{`
        @keyframes cardIn { from { opacity: 0; transform: translateY(18px) scale(.985) } to { opacity: 1; transform: none } }
        .card-in { animation: cardIn .6s cubic-bezier(.2,.7,.2,1) both; }
        @media (prefers-reduced-motion: reduce) { .card-in { animation: none; } }
      `}</style>

      {/* Blurred campus background */}
      <div
        className="absolute -inset-6 -z-30 scale-105 bg-cover bg-center blur-[8px]"
        style={{ backgroundImage: `url(${campusBg})` }}
        aria-hidden="true"
      />
      <div className="absolute inset-0 -z-20 bg-gradient-to-br from-[#14234b]/85 via-[#14234b]/65 to-[#8f0014]/50" aria-hidden="true" />

      {/* Back to home */}
      <a
        href="/"
        className="absolute left-4 top-4 inline-flex items-center gap-2 rounded-full bg-white/15 px-4 py-2 text-xs font-semibold text-white ring-1 ring-white/25 backdrop-blur transition hover:bg-white hover:text-[#14234b] focus-visible:outline focus-visible:outline-2 focus-visible:outline-[#f2c200] sm:left-8 sm:top-6"
      >
        <ArrowLeft size={14} /> Back to Home
      </a>

      {/* Split card */}
      <section className="card-in grid w-full max-w-[920px] overflow-hidden rounded-3xl bg-white shadow-[0_30px_80px_-20px_rgba(0,0,0,0.6)] md:grid-cols-[1fr_1.05fr]">
        {/* ── Brand panel ── */}
        <aside className="relative hidden flex-col justify-between overflow-hidden bg-gradient-to-br from-[#14234b] via-[#1b2f63] to-[#3a1230] p-10 text-white md:flex">
          <span className="absolute -right-16 -top-16 h-56 w-56 rounded-full bg-white/[0.06]" aria-hidden="true" />
          <span className="absolute -bottom-20 -left-12 h-64 w-64 rounded-full bg-[#8f0014]/30" aria-hidden="true" />
          <span className="absolute right-8 top-1/2 h-24 w-24 rounded-full border border-[#f2c200]/30" aria-hidden="true" />

          <div className="relative">
            <span className="grid h-24 w-24 place-items-center rounded-full bg-white p-2 shadow-xl ring-4 ring-[#f2c200]/60">
              <img src={logo} alt="M.C.E. Society’s Abeda Inamdar Senior College crest" className="h-full w-full object-contain" />
            </span>

            <p className="mt-6 text-[11px] font-semibold tracking-[0.25em] text-[#f2c200]">M.C.E. SOCIETY’S</p>
            <h1 className="mt-1 font-['Playfair_Display',serif] text-3xl font-bold leading-tight">
              Abeda Inamdar
              <br />
              Senior College
            </h1>
            <div className="mt-4 h-1 w-14 rounded-full bg-[#f2c200]" />
            <p className="mt-4 text-sm leading-relaxed text-white/80">
              Welcome to the college portal. Sign in to access your dashboard.
            </p>
          </div>

          <ul className="relative mt-8 space-y-4">
            {HIGHLIGHTS.map(({ icon: Icon, title, text }) => (
              <li key={title} className="flex items-center gap-3.5">
                <span className="grid h-10 w-10 shrink-0 place-items-center rounded-lg bg-white/10 text-[#f2c200] ring-1 ring-white/15">
                  <Icon size={20} />
                </span>
                <div className="leading-tight">
                  <p className="text-sm font-semibold">{title}</p>
                  <p className="text-xs text-white/65">{text}</p>
                </div>
              </li>
            ))}
          </ul>

          <p className="relative mt-8 font-['Playfair_Display',serif] text-lg italic text-white/90">
            “Read to Lead”
          </p>
        </aside>

        {/* ── Form panel ── */}
        <div className="flex flex-col justify-center px-7 py-10 sm:px-12">
          {/* Compact brand for mobile */}
          <div className="mb-7 flex items-center gap-3 md:hidden">
            <img src={logo} alt="" className="h-14 w-14 object-contain" />
            <div className="leading-tight">
              <p className="text-[10px] font-bold tracking-[0.2em] text-[#8f0014]">M.C.E. SOCIETY’S</p>
              <p className="font-['Playfair_Display',serif] text-lg font-bold text-[#14234b]">Abeda Inamdar Senior College</p>
            </div>
          </div>

          <h2 className="font-['Playfair_Display',serif] text-3xl font-bold text-[#14234b]">Welcome Back</h2>
          <p className="mt-1.5 text-sm text-slate-500">Sign in to access your dashboard.</p>

          <form onSubmit={handleSubmit} noValidate className="mt-8 space-y-5">
            {error && (
              <div
                role="alert"
                className="flex items-start gap-2 rounded-lg border border-[#8f0014]/20 bg-[#8f0014]/5 px-3.5 py-3 text-sm text-[#8f0014]"
              >
                <AlertCircle size={16} className="mt-0.5 shrink-0" /> {error}
              </div>
            )}

            <div>
              <label htmlFor="identifier" className="mb-1.5 block text-xs font-semibold tracking-wide text-[#14234b] uppercase">
                Username or Email
              </label>
              <div className={field}>
                <User size={18} className="shrink-0 text-slate-400" />
                <input
                  id="identifier"
                  type="text"
                  autoComplete="username"
                  placeholder="Enter your username or email"
                  value={identifier}
                  onChange={(e) => setIdentifier(e.target.value)}
                  className="h-full w-full bg-transparent text-sm text-slate-800 placeholder:text-slate-400 focus:outline-none"
                />
              </div>
            </div>

            <div>
              <div className="mb-1.5 flex items-center justify-between">
                <label htmlFor="password" className="text-xs font-semibold tracking-wide text-[#14234b] uppercase">
                  Password
                </label>
                <a href="#" className="text-xs font-semibold text-[#8f0014] hover:underline">
                  Forgot Password?
                </a>
              </div>
              <div className={field}>
                <Lock size={18} className="shrink-0 text-slate-400" />
                <input
                  id="password"
                  type={show ? "text" : "password"}
                  autoComplete="current-password"
                  placeholder="Enter your password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="h-full w-full bg-transparent text-sm text-slate-800 placeholder:text-slate-400 focus:outline-none"
                />
                <button
                  type="button"
                  onClick={() => setShow(!show)}
                  aria-label={show ? "Hide password" : "Show password"}
                  className="shrink-0 rounded p-1 text-slate-400 transition hover:text-[#8f0014] focus-visible:outline focus-visible:outline-2 focus-visible:outline-[#8f0014]"
                >
                  {show ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            <label className="flex w-fit cursor-pointer items-center gap-2.5 text-sm text-slate-600">
              <input
                type="checkbox"
                checked={remember}
                onChange={(e) => setRemember(e.target.checked)}
                className="h-4 w-4 rounded border-slate-300 accent-[#8f0014]"
              />
              Remember me
            </label>

            <button
              type="submit"
              disabled={loading}
              className="group flex h-12 w-full items-center justify-center gap-2 rounded-lg bg-gradient-to-b from-[#a30018] to-[#6d000f] text-sm font-bold tracking-wide text-white shadow-lg shadow-[#8f0014]/30 transition hover:shadow-xl hover:brightness-110 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#8f0014] disabled:cursor-not-allowed disabled:opacity-70"
            >
              {loading ? (
                <>
                  <Loader2 size={18} className="animate-spin motion-reduce:animate-none" /> Signing in…
                </>
              ) : (
                <>
                  Sign In <ArrowRight size={18} className="transition group-hover:translate-x-1" />
                </>
              )}
            </button>
          </form>

          <p className="mt-7 text-center text-sm text-slate-500">
            Don’t have an account?{" "}
            <a href="#" className="font-semibold text-[#8f0014] hover:underline">Contact Admin</a>
          </p>

          <p className="mt-8 border-t border-slate-100 pt-5 text-center text-[11px] text-slate-400">
            © 2026 M.C.E. Society’s Abeda Inamdar Senior College
          </p>
        </div>
      </section>
    </main>
  );
}